#!/bin/sh
# Sickbay installer for Alpine Linux (OpenRC). Generated by installer/build.sh: the app is the base64
# tarball after the __PAYLOAD_BELOW__ line at the end of this file.
# Re-runnable: replaces /opt/sickbay, keeps /var/lib/sickbay and /etc/conf.d/sickbay, and only adds settings
# that are missing from the config.
#
#   sh setup-sickbay.sh                        install / upgrade
#   SICKBAY_PORT=8775 sh setup-sickbay.sh      first install on another port
#   sh setup-sickbay.sh --uninstall            remove app and service (keeps data, config and backups)
set -eu

NAME=sickbay
DEFAULT_PORT=8774
APP_DIR=/opt/$NAME
DATA_DIR=/var/lib/$NAME
BACKUP_DIR=/var/backups/$NAME
CONF=/etc/conf.d/$NAME
INITD=/etc/init.d/$NAME
LOG=/var/log/$NAME.log
SVC_USER=$NAME
BACKUP_JOB=/etc/periodic/daily/$NAME-backup

UNINSTALL=
case "${1:-}" in
  "") ;;
  --uninstall) UNINSTALL=1 ;;
  *) echo "Unknown argument: $1 (use --uninstall or none)."; exit 1 ;;
esac
[ $# -le 1 ] || { echo "Too many arguments (use --uninstall or none)."; exit 1; }

# Household values baked in by build.sh from deploy/deploy.env (first install only; the environment wins).
# __DEPLOY_DEFAULTS__

[ "$(id -u)" = 0 ] || { echo "Run as root."; exit 1; }
command -v apk >/dev/null || { echo "This installer is for Alpine (apk)."; exit 1; }

if [ -n "$UNINSTALL" ]; then
  rc-service "$NAME" stop >/dev/null 2>&1 || true
  rc-update del "$NAME" default >/dev/null 2>&1 || true
  rm -f "$INITD" "$BACKUP_JOB"
  rm -rf "$APP_DIR"
  echo "Removed the app, its service and the backup job. Kept $DATA_DIR, $CONF and $BACKUP_DIR."
  exit 0
fi

conf_val() { sed -n "s/^$1=//p" "$CONF" 2>/dev/null | head -n1 | tr -d "\"'"; }

# An existing install keeps its port.
PORT=${SICKBAY_PORT:-$DEFAULT_PORT}
[ -f "$CONF" ] && PORT=$(conf_val SICKBAY_PORT) && PORT=${PORT:-$DEFAULT_PORT}
case "$PORT" in ""|*[!0-9]*) echo "SICKBAY_PORT must be a number."; exit 1 ;; esac

echo "==> Installing packages"
apk add --no-cache python3 py3-flask py3-gunicorn py3-jwt py3-cryptography sqlite tar ca-certificates >/dev/null

rc-service "$NAME" stop >/dev/null 2>&1 || true
if netstat -ltn 2>/dev/null | awk '{print $4}' | grep -q ":$PORT\$"; then
  echo "Port $PORT is already in use by something else. Re-run with SICKBAY_PORT=<free port>."; exit 1
fi

echo "==> Creating user and folders"
# BusyBox adduser -S puts a new user in "nogroup" unless told otherwise, so make the app's own group first.
grep -q "^$SVC_USER:" /etc/group || addgroup -S "$SVC_USER"
id "$SVC_USER" >/dev/null 2>&1 || adduser -S -D -H -h "$DATA_DIR" -s /sbin/nologin -G "$SVC_USER" "$SVC_USER"
mkdir -p "$DATA_DIR/files" "$BACKUP_DIR"
chmod 700 "$BACKUP_DIR"

echo "==> Unpacking app to $APP_DIR"
TMP=$(mktemp -d /tmp/sickbay-tmp.XXXXXX 2>/dev/null || mktemp -d)
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | ( cd "$TMP" && tar -xzf - )
rm -rf "$APP_DIR.new" && mv "$TMP/sickbay" "$APP_DIR.new"
rm -rf "$APP_DIR.old"; [ -d "$APP_DIR" ] && mv "$APP_DIR" "$APP_DIR.old"
mv "$APP_DIR.new" "$APP_DIR"; rm -rf "$APP_DIR.old" "$TMP"
chown -R root:root "$APP_DIR"
chown -R "$SVC_USER:$SVC_USER" "$DATA_DIR"
chmod 750 "$DATA_DIR"

# ---------------------------------------------------------------- config
add_setting() {  # add_setting FILE KEY VALUE COMMENT: only if KEY is not there yet
  grep -q "^$2=" "$1" 2>/dev/null && return 0
  printf '\n# %s\n%s="%s"\n' "$4" "$2" "$3" >> "$1"
  ADDED="${ADDED:-} $2"
}
[ -f "$CONF" ] || printf '# Sickbay settings. After editing: rc-service %s restart\n' "$NAME" > "$CONF"
add_setting "$CONF" SICKBAY_PORT "$PORT" "Port gunicorn listens on. It binds 127.0.0.1 only: cloudflared in this container is the one way in."
add_setting "$CONF" ALLOWED_EMAILS "${ALLOWED_EMAILS:-}" "The two users' emails (comma separated). Nobody else is admitted, whatever Access says."
add_setting "$CONF" USERS "${USERS:-}" "Display names: a@example.com=Alex,b@example.com=Sam"
add_setting "$CONF" CF_TEAM_DOMAIN "${CF_TEAM_DOMAIN:-}" "Cloudflare team domain, e.g. yourteam.cloudflareaccess.com"
add_setting "$CONF" CF_AUD "${CF_AUD:-}" "AUD tag of Sickbay's own Access application (no other application's)"
add_setting "$CONF" APP_NAME "${APP_NAME:-Logbook}" "Page title and home-screen name. Keep it neutral."
add_setting "$CONF" MAX_UPLOAD_MB "${MAX_UPLOAD_MB:-25}" "Largest upload in MB"
# Holds the household's emails, so root only: OpenRC runs as root and gives the service what it needs.
chmod 600 "$CONF"; chown root:root "$CONF"

# ---------------------------------------------------------------- service
cat > "$INITD" <<'EOF'
#!/sbin/openrc-run
name="sickbay"
description="Sickbay (Flask + gunicorn, loopback only)"
supervisor="supervise-daemon"
respawn_delay=5
respawn_max=10
respawn_period=600
command="/usr/bin/gunicorn"
command_user="sickbay"
output_log="/var/log/sickbay.log"
error_log="/var/log/sickbay.log"

depend() { need net; after firewall; }

start_pre() {
  : ${SICKBAY_PORT:=8774}
  command_args="--preload --workers 2 --threads 4 --timeout 60 --bind 127.0.0.1:${SICKBAY_PORT} --chdir /opt/sickbay --error-logfile /var/log/sickbay.log app:app"
  export HOME=/var/lib/sickbay DATA_DIR=/var/lib/sickbay
  export SICKBAY_PORT ALLOWED_EMAILS USERS CF_TEAM_DOMAIN CF_AUD APP_NAME MAX_UPLOAD_MB
  checkpath -f -o sickbay:sickbay -m 0640 /var/log/sickbay.log
}
EOF
chmod 755 "$INITD"

echo "==> Installing the nightly backup"
mkdir -p /etc/periodic/daily
install -m 755 "$APP_DIR/ops/sickbay-backup" "$BACKUP_JOB"
rc-update add crond default >/dev/null 2>&1 || true
rc-service crond start >/dev/null 2>&1 || true

rc-update add "$NAME" default >/dev/null 2>&1 || true
rc-service "$NAME" start >/dev/null 2>&1 || true

echo "==> Waiting for the app"
i=0
until wget -qO- "http://127.0.0.1:$PORT/healthz" 2>/dev/null | grep -q ok; do
  i=$((i + 1))
  if [ "$i" -ge 20 ]; then
    echo "The service did not answer. Check: tail -n 40 $LOG"
    exit 1
  fi
  sleep 1
done

echo "==> Taking a first backup"
"$BACKUP_JOB" || echo "    (backup reported a problem; see /var/log/$NAME-backup.log)"

echo
echo "Sickbay is running on 127.0.0.1:$PORT (loopback only)."
[ -n "${ADDED:-}" ] && echo "Settings added to $CONF:$ADDED"
if [ -z "$(conf_val ALLOWED_EMAILS)" ] || [ -z "$(conf_val CF_AUD)" ] || [ -z "$(conf_val CF_TEAM_DOMAIN)" ]; then
  echo "Not usable yet: set ALLOWED_EMAILS, USERS, CF_TEAM_DOMAIN and CF_AUD in $CONF, then: rc-service $NAME restart"
fi
echo "Point the Cloudflare Tunnel at http://127.0.0.1:$PORT (cloudflared in this container)."
exit 0
